$('abrir-post').onclick=async()=>{const p=posts.find(x=>x.id===$('post-lista').value);if(!p){notify('Selecciona un borrador.');return}if(dirty&&!confirm('Hay cambios sin guardar. ¿Abrir el borrador seleccionado?'))return;setBusy(true);try{post=normalizarPost(structuredClone(p));candidateId=post.candidato_id;temaActual=null;alternas={base:'',urls:[]};respaldar(null);current=0;clearImage();invalidateVisual();dirty=false;renderHooks();fillEditor();await cargarFotos();notify('Borrador abierto.')}catch(err){notify('Borrador abierto, pero '+err.message)}finally{setBusy(false)}};
$('guardar-post').onclick=async()=>{if(!db)return;if(imageValidation){notify('Espera a que termine la validación de la imagen.');return}setBusy(true);try{for(const ruta of rutasFotos()){const f=fotos.get(ruta);if(!f?.file)continue;const {error}=await db.storage.from('imagenes-privadas').upload(ruta,f.file,{contentType:f.file.type,upsert:false});if(error&&!/exist|duplicate/i.test(error.message))throw Error('una foto no se pudo subir. Intenta de nuevo o quítala.');delete f.file}const data=await invoke('guardar_post',post);post.id=data.id;post.revision=data.revision;post.estado=data.estado;dirty=false;respaldar(null);await refresh();syncControls();notify('Borrador guardado.')}catch(err){notify('No se pudo guardar: '+err.message)}finally{setBusy(false)}};
$('redactar').onclick=async()=>{if(busy)return;if(!post.fuente_primaria){notify('Pega primero el enlace de la fuente.');$('fuente-primaria').focus();return}if(post.laminas.some(l=>l.titulo||l.cuerpo)&&!confirm(`Esto reemplazará las láminas actuales${post.laminas.some(l=>l.imagen)?' y sus fotos propias':''}. ¿Continuar?`))return;setBusy(true);notify('Escribiendo el borrador: leo la fuente, redacto y verifico. Tarda entre 1 y 2 minutos; no cierres esta pestaña.');try{const data=await invoke('redactar',{alternativas:post.fuente_primaria===alternas.base?alternas.urls:[],fuente_primaria:post.fuente_primaria,formato:post.formato,tipo_gancho:post.tipo_gancho,tema:temaActual});if(!Array.isArray(data?.borrador?.laminas))throw Error('El servidor no entregó láminas.');modoFoto='';post.laminas=normalizarPost(data.borrador).laminas;post.descripcion=data.borrador.descripcion||'';post.sugerencia_imagen=data.borrador.sugerencia_imagen;post.ganchos=data.borrador.ganchos||[];if(data.formato)post.formato=data.formato;if(data.tipo_gancho)post.tipo_gancho=data.tipo_gancho;if(data.fuente_primaria&&data.fuente_primaria!==post.fuente_primaria){post.fuente_primaria=alternas.base=data.fuente_primaria;data.alertas=[...(data.alertas||[]),'La fuente principal bloquea la lectura automática: se usó '+host(data.fuente_primaria)]}current=0;marcarCambio(true);renderHooks();fillEditor();notify([data.advertencia||'Revisa cada afirmación y cifra en la fuente.',...(data.alertas||[])].join(' · '))}catch(err){notify('No se pudo redactar: '+err.message)}finally{setBusy(false)}};
function renderHooks(){ $('ganchos').innerHTML='<option value="">Elige un gancho</option>'+(post.ganchos||[]).map((h,i)=>`<option value="${i}">${esc(h.tipo)}: ${esc(h.texto)}</option>`).join('') }
$('ganchos').onchange=()=>{if($('ganchos').value==='')return;const h=post.ganchos?.[Number($('ganchos').value)];if(!h)return;post.tipo_gancho=h.tipo;post.laminas[0].titulo=h.texto;marcarCambio(true);fillEditor()};
async function reescribir(tipo){const contenido=tipo==='gancho'?{texto:post.laminas[0].titulo}:Object.fromEntries(['tipo','titulo','cuerpo','fuente','alt'].map(k=>[k,post.laminas[current][k]]));if(!post.fuente_primaria){notify('Pega primero el enlace de la fuente.');return}setBusy(true);notify('Reescribiendo…');try{const data=await invoke('reescribir',{fuente_primaria:post.fuente_primaria,formato:post.formato,tipo_gancho:post.tipo_gancho,tipo,instrucciones:$('instrucciones').value,contenido});if(!data?.contenido)throw Error('El servidor no entregó texto.');if(tipo==='gancho')post.laminas[0].titulo=data.contenido.texto;else post.laminas[current]={...post.laminas[current],...data.contenido};marcarCambio(true);fillEditor();notify(data.advertencia||'Revisa el texto con la fuente.')}catch(err){notify('No se pudo reescribir: '+err.message)}finally{setBusy(false)}}
$('reescribir-lamina').onclick=()=>reescribir('lamina');$('reescribir-gancho').onclick=()=>reescribir('gancho');
const OPCIONES={width:1080,height:1350,pixelRatio:1,quality:.92,style:{transform:'none'}},SAFARI=/^((?!chrome|android|crios|fxios).)*safari/i.test(navigator.userAgent);
async function prepararImagenes(){
 if(imageValidation)throw Error('Espera a que termine la validación de la imagen.');
 if(!cuentaActual())throw Error('Configura la cuenta de Instagram antes de preparar las láminas.');
 if(!fotoDe(0))throw Error('Carga la foto de la portada y comprueba su permiso.');
 if(rutasFotos().some(r=>!fotos.has(r)))throw Error('Una foto del borrador no cargó. Ábrelo de nuevo o vuelve a subirla.');
 if(post.laminas.length<6||post.laminas.length>10)throw Error('El carrusel debe tener de 6 a 10 láminas.');
 if(!post.laminas[0].titulo.trim())throw Error('La lámina 1 necesita el gancho como título.');if(!post.laminas.every(l=>(l.titulo.trim()||l.cuerpo.trim())&&l.alt.trim()))throw Error('Cada lámina necesita texto y texto alternativo.');
 const {toJpeg}=await import('https://cdn.jsdelivr.net/npm/html-to-image@1.11.13/+esm');await document.fonts.ready;
 if(!document.fonts.check('700 80px Inter')||!document.fonts.check('400 38px Inter'))throw Error('No cargaron las tipografías. Revisa la conexión y vuelve a intentar.');
 const before=current, imgs=[];
 try{for(let n=0;n<post.laminas.length;n++){current=n;updatePreview();const preview=$('preview');
  if(!cabe())throw Error(`El texto de la lámina ${n+1} no cabe. Acórtalo antes de aprobar.`);
  if(SAFARI)for(let k=0;k<2;k++)await toJpeg(preview,OPCIONES);
  // Diez láminas con foto tienen que caber juntas en la aprobación (9 MB): si una pesa más de su parte, baja la calidad.
  let url;for(const quality of [.92,.84,.76,.68]){url=await toJpeg(preview,{...OPCIONES,quality});if(url.length<1_150_000)break}if(!url.startsWith('data:image/jpeg;base64,'))throw Error('La imagen no se exportó como JPEG.');
  const base64=url.split(',')[1];if(base64.length>2666668)throw Error('Una lámina supera el tamaño permitido.');imgs.push(base64)}
  if(imgs.reduce((n,s)=>n+s.length,0)>11_800_000)throw Error('El conjunto de imágenes supera el tamaño permitido.');return imgs;
 }finally{current=before;fillEditor()}
}
$('preparar').onclick=async()=>{setBusy(true);try{prepared=await prepararImagenes();preparedVersion=visualVersion;preparedAccount=cuentaActual();$('imagenes-revision').innerHTML=prepared.map((x,i)=>`<figure><img src="data:image/jpeg;base64,${x}" alt="Lámina ${i+1} para revisión"><figcaption>Lámina ${i+1}</figcaption></figure>`).join('');notify('Revisa todas las imágenes, la cuenta y los créditos antes de aprobar.')}catch(err){invalidateVisual();notify('No se pudieron preparar las imágenes: '+err.message)}finally{setBusy(false)}};
$('aprobar').onclick=async()=>{if(!post.id||dirty||preparedVersion!==visualVersion||preparedAccount!==cuentaActual()){notify('Guarda y prepara esta versión antes de aprobar.');return}if(!confirm('¿Apruebas esta versión y las imágenes mostradas después de completar la revisión?'))return;setBusy(true);try{await invoke('aprobar_post',{id:post.id,revision:post.revision,nombre:usuario,imagenes:prepared});const {data,error}=await db.from('posts').select('*').eq('id',post.id).single();if(error||!data){dirty=true;throw Error('Se aprobó la versión, pero no se pudo recargar. Vuelve a abrir el borrador.')}post=data;dirty=false;invalidateVisual();notify('Versión aprobada. Descarga las imágenes revisadas o solicita su publicación web.');await refresh()}catch(err){notify('No se pudo completar la aprobación: '+err.message)}finally{setBusy(false)}};
async function imagenesAprobadas(){
 const latest=await db.from('posts').select('estado,revision,aprobacion,imagenes_aprobadas').eq('id',post.id).single();
 if(latest.error||!latest.data||!['aprobado','publicado'].includes(latest.data.estado)||latest.data.revision!==post.revision||JSON.stringify(latest.data.imagenes_aprobadas)!==JSON.stringify(post.imagenes_aprobadas))throw Error('La aprobación cambió; vuelve a abrir el borrador.');
 const account=await db.from('config').select('valor').eq('clave','cuenta_instagram').single();
 if(account.error||account.data?.valor!==post.aprobacion?.cuenta_instagram)throw Error('La cuenta configurada cambió; revisa y aprueba otra vez.');
 const m=post.imagenes_aprobadas;if(!Array.isArray(m)||m.length!==post.laminas.length)throw Error('No están disponibles las imágenes aprobadas.');const out=[];
 for(const item of m){if(typeof item.path!=='string'||!item.path.startsWith(`aprobaciones/${post.id}/`)||!/^[0-9a-f]{64}$/.test(item.sha256))throw Error('La referencia de imagen aprobada no es válida.');const {data,error}=await db.storage.from('imagenes-privadas').download(item.path);if(error||!data)throw Error('No se pudo cargar una imagen aprobada.');const bytes=await data.arrayBuffer();const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');if(hash!==item.sha256)throw Error('Una imagen cambió desde la aprobación; no se descargará.');out.push(bytes)}return out;
}
$('descargar').onclick=async()=>{if(dirty||!['aprobado','publicado'].includes(post.estado)||!cuentaActual()||post.aprobacion?.cuenta_instagram!==cuentaActual()){notify('Guarda y aprueba esta versión con la cuenta actual antes de descargar.');return}setBusy(true);try{const [{default:JSZip},images]=await Promise.all([import('https://cdn.jsdelivr.net/npm/jszip@3.10.1/+esm'),imagenesAprobadas()]);const zip=new JSZip();images.forEach((data,i)=>zip.file(`lamina-${String(i+1).padStart(2,'0')}.jpg`,data));const blob=await zip.generateAsync({type:'blob'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='carrusel-nucleo-ia.zip';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('ZIP de las imágenes aprobadas descargado.')}catch(err){notify('No se pudo descargar: '+err.message)}finally{setBusy(false)}};
