$('publicar-web').onclick=async()=>{if(dirty||post.estado!=='aprobado'||!cuentaActual()||post.aprobacion?.cuenta_instagram!==cuentaActual()){notify('Guarda y aprueba esta versión con la cuenta actual antes de publicar.');return}if(!confirm('¿Publicar esta versión aprobada en la web?'))return;setBusy(true);try{const data=await invoke('publicar_web',{id:post.id,revision:post.revision});post.estado=data.estado;post.url_web=data.url;dirty=false;notify(`Nota publicada: ${data.url}`);await refresh()}catch(err){notify('No se pudo publicar: '+err.message)}finally{setBusy(false)}};
const NOMBRES_AGENTE={radar_noticias:'Radar: investigación y orden de temas',radar_academico:'Radar académico: fichas de papers',redactar:'Redacción del carrusel',voz:'Voz y estilo del Núcleo',verificar:'Verificación contra la fuente'};
