function setVersions(){const agente=$('prompt-agente').value;const ps=prompts.filter(p=>p.agente===agente).sort((a,b)=>b.version-a.version);$('prompt-version').innerHTML=ps.map(p=>`<option value="${p.id}">Versión ${p.version}${p.activa?' · activa':''}</option>`).join('');setPrompt()}
